    'topo.tour.p2.external.title': 'Usuário / Admin',
    'topo.tour.p2.external.caption': 'Tudo começa aqui: o operador acessa o painel pelo navegador (HTTPS). É a borda externa — quem comanda e observa a rede.',
    'topo.tour.p2.admin.title': 'Acesso & Administração',
    'topo.tour.p2.admin.caption': 'O Caddy termina o TLS e autentica; o painel FastAPI faz observabilidade leve (telemetria, logs, controle do lab) — sem Prometheus/Grafana.',
    'topo.tour.p2.ran.title': 'RAN + RIC (host nativo)',
    'topo.tour.p2.ran.caption': 'O coração O-RAN: o UE simulado fala por rádio (RFSIM) com o gNB; o gNB reporta ao near-RT RIC pela E2, e os xApps rodam a inteligência (ex.: previsão de throughput por UE).',
    'topo.tour.p2.nonrt.title': 'Non-RT RIC (SMO) — políticas A1',
    'topo.tour.p2.nonrt.caption': 'O par LENTO do loop rápido: enquanto a banda verde reage em 10 ms–1 s (E2), aqui o PMS — Non-RT RIC, construído em ARM64 nativo — decide em horizonte > 1 s: aprende com o histórico, define políticas e as desce pela interface A1 aos near-RT (no lab, os 3 simuladores; o tracejado até o FlexRIC é a terminação que a Fase 2 traz). É onde os rApps viverão — o rápido reage, o lento aprende e guia.',
    'topo.tour.p2.oransc.title': 'near-RT O-RAN SC — A1 real (Fase 2 em curso)',
    'topo.tour.p2.oransc.caption': 'A Fase 2 nascendo: o ric_a1mediator é a terminação A1 DE VERDADE (a porta que o FlexRIC não tem), e o ric_dbaas é o banco da pilha — Redis + SDL, onde vivem R-NIB e o estado A1. Ambos compilados da fonte em ARM64 (a RMR ganhou patch de arquitetura). Quando e2term/e2mgr/submgr chegarem, esta banda vira o near-RT completo e o tracejado A1 some.',
    'topo.journey.p2.a1real.title': 'A1 real + o banco (Fase 2)',
    'topo.journey.p2.a1real.caption': 'O primeiro pedaço da Fase 2 no ar: o ric_a1mediator aceita políticas pela API A1AP v2 e persiste o estado via SDL no ric_dbaas (Redis) — o banco que o Non-RT não tem. O tracejado PMS⇢Mediator é o próximo passo: o perfil oran liga o PMS de verdade nele.',
    'topo.tour.p2.core-cp.title': 'Core 5G — Plano de Controle (SBA)',
    'topo.tour.p2.core-cp.caption': 'Só sinalização (CUPS): o AMF recebe o gNB pela N2 e o NAS do UE (N1), autentica via AUSF/UDM (dados no UDR/MySQL) e pede a sessão ao SMF pela N11; o SMF programa o UPF pela N4.',
    'topo.tour.p2.core-up.title': 'Core 5G — Plano de Usuário',
    'topo.tour.p2.core-up.caption': 'Só dados (CUPS): os pacotes do UE seguem gNB→UPF (N3/GTP-U) e saem para a internet pela N6 — sem passar pelas NFs de controle.',
    'topo.tour.p1.external.title': 'Usuário / Admin',
