    'an.r_swap_d': 'O primeiro byte de swap é o sinal mais confiável de que o box vai travar — quando ele começa a paginar, o SSH cai antes de a memória acabar.',
    'an.r_swap_f': 'Desligue o projeto que não está em uso antes de subir o outro.',
    'an.r_carga_t': 'Carga {c} para {n} vCPU',
    'an.r_carga_ok': 'É o esperado com o rádio no ar: o <b>gNB</b> e o <b>UE</b> do RFSIM processam sinal em tempo real e consomem perto de 280% de CPU sozinhos. O guardrail mantém o CPU 0 fora do laboratório, e é por isso que o painel e o SSH continuam respondendo.',
