    'an.r_snr_d': 'Abaixo de 20 dB o canal deixa de ser bom (referência da aula 04). No RFSIM isso não acontece sozinho: é interferência ou perfil de distância aplicado pelo painel.',
    'an.r_snr_f': 'Confira se há interferência ligada antes de atribuir a queda ao core.',
