    'loginfo.amf.t': 'AMF — Access & Mobility Management',
    'loginfo.amf.d': 'The UE\'s first contact with the core (N1/N2). The log shows the <b>NGAP</b> signalling with the gNB: NG Setup, Initial UE Message, authentication and registration.',
    'loginfo.amf.w': '“NG Setup … successful” and the UE registration (Registration accept).',
    'loginfo.smf.t': 'SMF — Session Management',
    'loginfo.smf.d': 'Creates/manages the UE\'s PDU session and programs the UPF via <b>N4/PFCP</b>; assigns the UE\'s IP.',
    'loginfo.smf.w': '“PFCP association” with the UPF and “PDU session established”.',
    'loginfo.upf.t': 'UPF — User Plane Function',
    'loginfo.upf.d': 'Forwards the UE\'s data traffic (<b>N3 GTP-U</b> ↔ <b>N6</b> internet). Programmed by the SMF via PFCP.',
    'loginfo.upf.w': 'The PFCP association and the active data path (GTP-U).',
    'loginfo.ausf.t': 'AUSF — Authentication Server',
