    'loginfo.udr.t': 'UDR — Unified Data Repository',
    'loginfo.udr.d': 'Subscriber data access layer over the database (MongoDB/MySQL).',
    'loginfo.udr.w': 'Subscriber profile reads/writes.',
    'loginfo.nrf.t': 'NRF — NF Repository Function',
