    'loginfo.bsf.w': 'Registered session bindings.',
    'loginfo.nssf.t': 'NSSF — Network Slice Selection',
    'loginfo.nssf.d': 'Selects the right <b>network slice</b> (S-NSSAI) for the UE at registration.',
    'loginfo.nssf.w': 'Slice selection requested by the AMF.',
    'loginfo.mongodb.t': 'MongoDB — subscriber database',
    'loginfo.mongodb.d': 'Data backend for the UDR/WebUI (Open5GS): IMSI, keys, profile, slice.',
    'loginfo.mongodb.w': 'UDR connections and queries.',
    'loginfo.mysql.t': 'MySQL — subscriber database (OAI)',
    'loginfo.mysql.d': 'Data backend for the OAI Core\'s UDR: subscribers and profiles.',
    'loginfo.mysql.w': 'UDR connections (oai-udr).',
