    'topo.tour.p2.external.title': 'User / Admin',
    'topo.tour.p2.external.caption': 'Everything starts here: the operator reaches the panel from the browser (HTTPS). It is the outer edge — who commands and observes the network.',
    'topo.tour.p2.admin.title': 'Access & Administration',
    'topo.tour.p2.admin.caption': 'Caddy terminates TLS and authenticates; the FastAPI panel does light observability (telemetry, logs, lab control) — no Prometheus/Grafana.',
    'topo.tour.p2.ran.title': 'RAN + RIC (native host)',
    'topo.tour.p2.ran.caption': 'The O-RAN heart: the simulated UE talks over radio (RFSIM) to the gNB; the gNB reports to the near-RT RIC over E2, and the xApps run the intelligence (e.g. per-UE throughput prediction).',
    'topo.tour.p2.nonrt.title': 'Non-RT RIC (SMO) — A1 policies',
    'topo.tour.p2.nonrt.caption': 'The SLOW pair of the fast loop: while the green band reacts in 10 ms–1 s (E2), here the PMS — Non-RT RIC, built natively for ARM64 — decides on a > 1 s horizon: learns from history, sets policies and pushes them over the A1 interface to the near-RTs (in this lab, the 3 simulators; the dashed line to FlexRIC is the termination Phase 2 brings). This is where rApps will live — the fast one reacts, the slow one learns and guides.',
    'topo.tour.p2.oransc.title': 'O-RAN SC near-RT — real A1 (Phase 2 underway)',
    'topo.tour.p2.oransc.caption': 'Phase 2 being born: ric_a1mediator is the REAL A1 termination (the door FlexRIC lacks) and ric_dbaas is the stack database — Redis + SDL, home of the R-NIB and A1 state. Both compiled from source for ARM64 (RMR got an architecture patch). Once e2term/e2mgr/submgr arrive, this band becomes the full near-RT and the dashed A1 disappears.',
    'topo.journey.p2.a1real.title': 'Real A1 + the database (Phase 2)',
    'topo.journey.p2.a1real.caption': 'The first piece of Phase 2 live: ric_a1mediator accepts policies over the A1AP v2 API and persists state via SDL into ric_dbaas (Redis) — the database the Non-RT lacks. The dashed PMS⇢Mediator is the next step: the oran profile wires the PMS to it for real.',
    'topo.tour.p2.core-cp.title': '5G Core — Control Plane (SBA)',
    'topo.tour.p2.core-cp.caption': 'Signalling only (CUPS): the AMF receives the gNB over N2 and the UE’s NAS (N1), authenticates via AUSF/UDM (data in UDR/MySQL) and requests the session from the SMF over N11; the SMF programs the UPF over N4.',
    'topo.tour.p2.core-up.title': '5G Core — User Plane',
    'topo.tour.p2.core-up.caption': 'Data only (CUPS): the UE’s packets go gNB→UPF (N3/GTP-U) and exit to the internet over N6 — without passing through the control NFs.',
    'topo.tour.p1.external.title': 'User / Admin',
    'topo.tour.p1.external.caption': 'Everything starts here: the operator reaches the panel from the browser (HTTPS). It is the outer edge — who commands and observes the network.',
    'topo.tour.p1.admin.title': 'Access & Administration',
    'topo.tour.p1.admin.caption': 'Caddy terminates TLS and authenticates; the FastAPI panel observes the lab; the Open5GS WebUI registers subscribers in MongoDB.',
    'topo.tour.p1.ran.title': 'RAN (UERANSIM)',
    'topo.tour.p1.ran.caption': 'UERANSIM simulates gNB + UE in the same container: NG Setup (N2), UE registration (NAS/N1, carried inside N2) and PDU session; the UE’s traffic originates on uesimtun0 (10.60.x).',
    'topo.tour.p1.core-cp.title': '5G Core — Control Plane (SBA)',
    'topo.tour.p1.core-cp.caption': 'Signalling only (CUPS): the AMF registers the UE and authenticates via AUSF/UDM/UDR (MongoDB); the NSSF picks the slice, the PCF decides QoS; over N11 the AMF triggers the SMF, which programs the UPFs over N4.',
    'topo.tour.p1.core-up.title': '5G Core — User Plane',
