    'an.r_swap_t': 'Swap in use: {mb} MB',
    'an.r_swap_d': 'The first byte of swap is the most reliable sign the box is about to freeze — once it starts paging, SSH drops before memory runs out.',
    'an.r_swap_f': 'Turn off the project you are not using before bringing the other one up.',
    'an.r_carga_t': 'Load {c} for {n} vCPU',
    'an.r_carga_ok': 'Expected with the radio up: the RFSIM <b>gNB</b> and <b>UE</b> process signal in real time and take close to 280% CPU on their own. The guardrail keeps CPU 0 out of the lab, which is why the panel and SSH stay responsive.',
    'an.r_carga_ok_f': 'Only worry if swap leaves zero: that is what precedes the freeze.',
