    'topo.tour.p2.external.title': 'Usuario / Admin',
    'topo.tour.p2.external.caption': 'Todo empieza aquí: el operador accede al panel por el navegador (HTTPS). Es el borde externo — quien controla y observa la red.',
    'topo.tour.p2.admin.title': 'Acceso y administración',
    'topo.tour.p2.admin.caption': 'Caddy termina el TLS y autentica; el panel FastAPI hace observabilidad ligera (telemetría, logs, control del lab) — sin Prometheus/Grafana.',
    'topo.tour.p2.ran.title': 'RAN + RIC (host nativo)',
    'topo.tour.p2.ran.caption': 'El corazón O-RAN: el UE simulado habla por radio (RFSIM) con el gNB; el gNB reporta al near-RT RIC por E2, y los xApps ejecutan la inteligencia (p. ej., predicción de throughput por UE).',
    'topo.tour.p2.nonrt.title': 'Non-RT RIC (SMO) — políticas A1',
    'topo.tour.p2.nonrt.caption': 'El par LENTO del bucle rápido: mientras la banda verde reacciona en 10 ms–1 s (E2), aquí el PMS — Non-RT RIC, construido en ARM64 nativo — decide en horizonte > 1 s: aprende del histórico, define políticas y las baja por la interfaz A1 a los near-RT (en el lab, los 3 simuladores; la línea discontinua hasta FlexRIC es la terminación que trae la Fase 2). Aquí vivirán los rApps.',
    'topo.tour.p2.oransc.title': 'near-RT O-RAN SC — A1 real (Fase 2 en curso)',
    'topo.tour.p2.oransc.caption': 'La Fase 2 naciendo: ric_a1mediator es la terminación A1 REAL (la puerta que FlexRIC no tiene) y ric_dbaas es la base de datos de la pila — Redis + SDL, hogar del R-NIB y del estado A1. Ambos compilados desde la fuente en ARM64. Cuando lleguen e2term/e2mgr/submgr, esta banda será el near-RT completo.',
    'topo.journey.p2.a1real.title': 'A1 real + la base de datos (Fase 2)',
    'topo.journey.p2.a1real.caption': 'La primera pieza de la Fase 2 en marcha: ric_a1mediator acepta políticas por la API A1AP v2 y persiste el estado vía SDL en ric_dbaas (Redis) — la base que el Non-RT no tiene. La línea discontinua PMS⇢Mediator es el siguiente paso.',
    'topo.tour.p2.core-cp.title': 'Core 5G — Plano de Control (SBA)',
    'topo.tour.p2.core-cp.caption': 'Solo señalización (CUPS): el AMF recibe el gNB por N2 y el NAS del UE (N1), autentica vía AUSF/UDM (datos en UDR/MySQL) y pide la sesión al SMF por N11; el SMF programa el UPF por N4.',
    'topo.tour.p2.core-up.title': 'Core 5G — Plano de Usuario',
    'topo.tour.p2.core-up.caption': 'Solo datos (CUPS): los paquetes del UE van gNB→UPF (N3/GTP-U) y salen a internet por N6 — sin pasar por las NFs de control.',
