    'topo.tour.p2.external.title': 'Utilisateur / Admin',
    'topo.tour.p2.external.caption': 'Tout commence ici : l’opérateur accède au panneau via le navigateur (HTTPS). C’est la bordure externe — qui commande et observe le réseau.',
    'topo.tour.p2.admin.title': 'Accès & administration',
    'topo.tour.p2.admin.caption': 'Caddy termine le TLS et authentifie ; le panneau FastAPI assure une observabilité légère (télémétrie, logs, contrôle du lab) — sans Prometheus/Grafana.',
    'topo.tour.p2.ran.title': 'RAN + RIC (hôte natif)',
    'topo.tour.p2.ran.caption': 'Le cœur O-RAN : l’UE simulé parle par radio (RFSIM) au gNB ; le gNB rapporte au near-RT RIC via E2, et les xApps exécutent l’intelligence (ex. : prédiction de débit par UE).',
    'topo.tour.p2.nonrt.title': 'Non-RT RIC (SMO) — politiques A1',
    'topo.tour.p2.nonrt.caption': 'Le binôme LENT de la boucle rapide : tandis que la bande verte réagit en 10 ms–1 s (E2), ici le PMS — Non-RT RIC, compilé nativement pour ARM64 — décide sur un horizon > 1 s : il apprend de l’historique, définit des politiques et les pousse via l’interface A1 vers les near-RT (dans ce lab, les 3 simulateurs ; le pointillé vers FlexRIC est la terminaison qu’apporte la Phase 2). C’est ici que vivront les rApps.',
    'topo.tour.p2.oransc.title': 'near-RT O-RAN SC — A1 réel (Phase 2 en cours)',
    'topo.tour.p2.oransc.caption': 'La Phase 2 qui naît : ric_a1mediator est la terminaison A1 RÉELLE (la porte qui manque à FlexRIC) et ric_dbaas est la base de la pile — Redis + SDL, foyer du R-NIB et de l’état A1. Tous deux compilés depuis les sources pour ARM64. Quand e2term/e2mgr/submgr arriveront, cette bande deviendra le near-RT complet.',
    'topo.journey.p2.a1real.title': 'A1 réel + la base (Phase 2)',
    'topo.journey.p2.a1real.caption': 'La première pièce de la Phase 2 en marche : ric_a1mediator accepte les politiques via l’API A1AP v2 et persiste l’état via SDL dans ric_dbaas (Redis) — la base qui manque au Non-RT. Le pointillé PMS⇢Mediator est la prochaine étape.',
    'topo.tour.p2.core-cp.title': 'Cœur 5G — Plan de contrôle (SBA)',
    'topo.tour.p2.core-cp.caption': 'Signalisation seule (CUPS) : l’AMF reçoit le gNB via N2 et le NAS de l’UE (N1), authentifie via AUSF/UDM (données dans UDR/MySQL) et demande la session au SMF via N11 ; le SMF programme l’UPF via N4.',
    'topo.tour.p2.core-up.title': 'Cœur 5G — Plan utilisateur',
    'topo.tour.p2.core-up.caption': 'Données seules (CUPS) : les paquets de l’UE vont gNB→UPF (N3/GTP-U) et sortent vers Internet via N6 — sans passer par les NFs de contrôle.',
    'topo.tour.p1.external.title': 'Utilisateur / Admin',
    'topo.tour.p1.external.caption': 'Tout commence ici : l’opérateur accède au panneau via le navigateur (HTTPS). C’est la bordure externe — qui commande et observe le réseau.',
    'topo.tour.p1.admin.title': 'Accès & administration',
    'topo.tour.p1.admin.caption': 'Caddy termine le TLS et authentifie ; le panneau FastAPI observe le lab ; la WebUI d’Open5GS enregistre les abonnés dans MongoDB.',
    'topo.tour.p1.ran.title': 'RAN (UERANSIM)',
    'topo.tour.p1.ran.caption': 'UERANSIM simule gNB + UE dans le même conteneur : NG Setup (N2), enregistrement de l’UE (NAS/N1, transporté dans N2) et session PDU ; le trafic de l’UE naît sur uesimtun0 (10.60.x).',
    'topo.tour.p1.core-cp.title': 'Cœur 5G — Plan de contrôle (SBA)',
    'topo.tour.p1.core-cp.caption': 'Signalisation seule (CUPS) : l’AMF enregistre l’UE et authentifie via AUSF/UDM/UDR (MongoDB) ; le NSSF choisit la slice, le PCF décide la QoS ; via N11 l’AMF déclenche le SMF, qui programme les UPFs via N4.',
    'topo.tour.p1.core-up.title': 'Cœur 5G — Plan utilisateur',
    'topo.tour.p1.core-up.caption': 'Données seules (CUPS) : l’UPF-A achemine le trafic de l’UE (N3) vers le Data Network (N6, iperf3) ; l’UPF-B prend le relais lors du test de failover.',
    'pc.p1_ran_title': 'RAN — UERANSIM gNB + UE simulés (N2/N3)',
