    'topo.journey.p2.start.title': 'Le téléphone s’allume',
    'topo.journey.p2.start.caption': 'L’UE (nrUE) démarre — un téléphone 5G simulé (IMSI 208950000000032, slice SST=222/SD=123). À partir d’ici, il tente de se connecter au réseau.',
